import { useEffect, useMemo, useState } from 'react';
import { createProject, getProjects } from './api';
import './projects.css';

function Projects({ search = '', userRole }) {
	const [projects, setProjects] = useState([]);
	const [projectName, setProjectName] = useState('');
	const [description, setDescription] = useState('');
	const [isLoading, setIsLoading] = useState(true);
	const [error, setError] = useState('');

	useEffect(() => {
		getProjects()
			.then((response) => setProjects(response.data))
			.catch((loadError) => setError(loadError.message))
			.finally(() => setIsLoading(false));
	}, []);

	const visibleProjects = useMemo(() => {
		const query = search.toLowerCase();
		return projects.filter((project) => !query || `${project.name} ${project.description}`.toLowerCase().includes(query));
	}, [projects, search]);

	async function handleSubmit(event) {
		event.preventDefault();
		setError('');
		try {
			const response = await createProject({ name: projectName, description });
			setProjects((currentProjects) => [response.data, ...currentProjects]);
			setProjectName('');
			setDescription('');
		} catch (submitError) {
			setError(submitError.message);
		}
	}

	return (
		<section className="projects-page" aria-labelledby="projects-title">
			<div className="projects-heading">
				<div><p className="dashboard-label">Workspace planning</p><h2 id="projects-title">Projects</h2><p>Organize related tasks into focused workstreams.</p></div>
				<span className="project-count"><strong>{projects.length}</strong> projects</span>
			</div>

			{userRole !== 'User' && <form className="project-create-form" onSubmit={handleSubmit}><div><label htmlFor="project-name">Project name</label><input id="project-name" value={projectName} onChange={(event) => setProjectName(event.target.value)} placeholder="e.g. Website launch" maxLength="80" required /></div><div><label htmlFor="project-description">Description</label><input id="project-description" value={description} onChange={(event) => setDescription(event.target.value)} placeholder="What is this project about?" /></div><button type="submit">Create project</button></form>}
			{error && <p className="project-error" role="alert">{error}</p>}
			{isLoading && <p className="project-empty">Loading projects...</p>}
			{!isLoading && !error && visibleProjects.length === 0 && <p className="project-empty">No projects found.</p>}
			{!isLoading && <div className="project-grid">{visibleProjects.map((project) => <article className="project-card" key={project._id}><div className="project-card-top"><span className="project-mark">{project.name.charAt(0).toUpperCase()}</span><span className="project-date">Updated {new Date(project.updatedAt).toLocaleDateString()}</span></div><h3>{project.name}</h3><p>{project.description || 'No description added yet.'}</p><div className="project-meta"><span>Owner: {project.owner?.fullname || 'Unknown'}</span><span>{project.members?.length || 0} member{project.members?.length === 1 ? '' : 's'}</span></div></article>)}</div>}
		</section>
	);
}

export default Projects;
